import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand,type GameState} from '@madou/engine';
import {getAction} from '@madou/catalog';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
/** Actual CHANT and full intervening turn order before one or three locked hits. */
export function makeR6MaaiScenario(players:{id:string;name:string}[],three=false,maaiCardInstanceId?:string):GameState{
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,'侍大将のシン');assignCharacter(s,b,'黒騎士ガーウィン');assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,spirit:20};
 const sword=takeCard(s,a,'天地百撃斬'),advance=takeCard(s,a,'踏み込み／蹴る'),bm=takeCard(s,b,maaiCardInstanceId??'a2-p07-r1c1'),cm=takeCard(s,c,maaiCardInstanceId==='a2-p07-r1c1'||!maaiCardInstanceId?'a2-p07-r1c2':'a2-p07-r1c1');trimHand(s,a,sword,advance);trimHand(s,b,bm);trimHand(s,c,cm);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand,dice=Array(100).fill(1)){const input={actorId,command},e={...entropy(),dice},r=transition(s,input,e);if(!r.ok)throw Error(`S11_12_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('S11_12_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('S11_12_CARDS');}
 readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});act(a,{type:'CHANT',cardInstanceId:sword});
 for(let n=0;n<50;n++){const actor=s.seatOrder[s.turnSeat]!;if(s.phase==='action'){if(actor===a)break;act(actor,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(actor,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(actor,{type:'END_TURN',discardIds:s.players[actor]!.hand.slice(0,Math.max(0,s.players[actor]!.hand.length-gameStats(s,actor).handLimit))});else if(s.phase==='turn-start')act(actor,{type:'START_TURN'});else if(s.phase==='draw')act(actor,{type:'CHOOSE_DRAW',draw:false});else throw Error('S11_12_TURN');}
 act(a,{type:'ATTACK',cardInstanceId:sword,targetIds:three?[b]:[b,c],dedicated:true});for(let n=0;n<300;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'},w.kind==='damage'?[three?3:1]:Array(100).fill(1));}throw Error('S11_12_WINDOW');
}
